// When this Spring Boot controller handles a request:
@RestController
public class OrderController {

    private final OrderService service;

    public OrderController(OrderService service) {
        this.service = service;  // Reference to service object
    }

    @GetMapping("/orders/{id}")
    public Order getOrder(@PathVariable Long id) {
        // 1. ClassLoader: Loads Order.class if not already loaded
        // 2. Stack: Creates frame for getOrder() method
        //    Local variable 'id' stored in this frame
        var order = service.findById(id);
        // 3. Heap: Order object created here
        // 4. Method Area: Holds Order class metadata
        // 5. Execution Engine: JIT compiles this if called frequently
        return order;  // Reference returned, object stays in heap
    }
}

// Runtime Data Areas used:
// - Heap: OrderController instance, OrderService instance, Order object
// - Stack: getOrder() method frame with local variable 'id' and 'order'
// - Method Area: OrderController.class, OrderService.class, Order.class metadata
