// Demonstrating lazy loading and ClassLoader hierarchy
public class ClassLoaderDemo {

    public static void main(String[] args) {
        // At this point, Employee class is NOT loaded yet

        System.out.println("Application started");

        // NOW Employee.class is loaded when first referenced
        Employee emp = new Employee("Alice");

        // Check which ClassLoader loaded Employee
        ClassLoader empLoader = Employee.class.getClassLoader();
        System.out.println("Employee loaded by: " + empLoader);
        // Output: sun.misc.Launcher$AppClassLoader (Application ClassLoader)

        // Check String's ClassLoader (core Java class)
        ClassLoader stringLoader = String.class.getClassLoader();
        System.out.println("String loaded by: " + stringLoader);
        // Output: null (Bootstrap ClassLoader, written in C, has no Java object)

        // Parent delegation chain
        System.out.println("Parent of App: " + empLoader.getParent());
        // Output: sun.misc.Launcher$ExtClassLoader
        System.out.println("Parent of Ext: " + empLoader.getParent().getParent());
        // Output: null (Bootstrap is the root)
    }
}

record Employee(String name) {}
