```java
// Demonstrating warm-up effect from JIT compilation
public class JitPerformanceDemo {

    public static void main(String[] args) {
        // Warm-up phase: JIT hasn't compiled yet
        for (int i = 0; i < 5; i++) {
            long start = System.nanoTime();
            long sum = calculateSum(1_000_000);
            long duration = System.nanoTime() - start;
            System.out.println("Iteration " + i + ": " + duration + " ns");
            // Early iterations are slower (interpreted)
            // Later iterations become faster (JIT compiled)
        }

        // Steady-state phase: JIT has compiled hot methods
        for (int i = 5; i < 10; i++) {
            long start = System.nanoTime();
            long sum = calculateSum(1_000_000);
            long duration = System.nanoTime() - start;
            System.out.println("Iteration " + i + ": " + duration + " ns");
            // These are consistently faster
        }
    }

    // This method becomes a hot spot after repeated calls
    private static long calculateSum(int n) {
        long sum = 0;
        for (int i = 1; i <= n; i++) {
            sum += i;  // JIT will optimize this loop
        }
        return sum;
    }
}
